css:
:scope { width: min(100%, 820px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 2 / span 21; grid-row: 1 / span 9; font-family: var(--os-font-heading); font-size: 31px; font-weight: 400; line-height: 2.19; letter-spacing: 0.02em; text-align: center; color: var(--os-color-background); }
.gx__i2 { grid-column: 1 / span 24; grid-row: 11 / span 9; font-family: var(--os-font-heading); font-size: 23px; font-weight: 400; line-height: 1.48; letter-spacing: 0.02em; text-align: center; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 18px; }
}
